//! Moved from `crates/oneiron/src/memory/search_hybrid.rs` (lib split W2: wire types below the lib).
//! `oneiron` re-exports each item at its old path.

use oneiron_contracts::memory::MemoryError;
use oneiron_contracts::memory::MemoryResult;
use oneiron_contracts::retrieval_telemetry::RetrievalBlendWeights;
use oneiron_contracts::retrieval_telemetry::RetrievalScoreComponent;
use serde::Deserialize;
use serde::Serialize;

/// Explicit channel inputs. Omitted channels do not run; vectors and phonetic
/// codes are supplied by the caller, not generated by an unconfigured model.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridSearchRequest {
    #[serde(default)]
    pub query: Option<String>,
    #[serde(default)]
    pub query_vector: Option<Vec<f32>>,
    #[serde(default)]
    pub phonetic_codes: Vec<String>,
    #[serde(default)]
    pub ppr: Option<HybridPprQuery>,
    #[serde(default)]
    pub temporal: Option<HybridTemporalQuery>,
    /// Pins scoring inputs for repeatable ranking on the same admitted corpus.
    /// This is not a historical read or a change to stored learned weights.
    #[serde(default)]
    pub replay: Option<HybridRankReplay>,
    pub limit: usize,
    /// The caller's retrieval filter (FIX 3977): bound before candidate
    /// generation, so it narrows every channel, seed and terminal read.
    #[serde(default)]
    pub filter: Option<oneiron_contracts::gate::ReadFilterInput>,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridPprQuery {
    /// Short record refs or 32-hex entity ids, admitted by the caller's lane.
    pub seeds: Vec<String>,
    pub depth: u32,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridTemporalQuery {
    pub start: u64,
    pub end: u64,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridRankReplay {
    /// Unix seconds for temporal interpretation and time-dependent scoring.
    pub now: u64,
    pub blend_weights: RetrievalBlendWeights,
}

/// Evidence for one admitted result, available even when telemetry is off.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct HybridSearchHit {
    pub entity_ref: String,
    pub source_revision_ref: Option<String>,
    pub score: f32,
    pub access_factor: Option<f32>,
    pub components: Vec<RetrievalScoreComponent>,
}

impl HybridSearchRequest {
    pub fn validate(&self) -> MemoryResult<()> {
        caps::check_limit_nonzero(self.limit)?;
        if let Some(vector) = &self.query_vector {
            caps::check_dimensions(vector.len())?;
            if vector.iter().any(|value| !value.is_finite()) {
                return Err(MemoryError::bad_request("query_vector must be finite"));
            }
        }
        for code in &self.phonetic_codes {
            if code.trim().is_empty() {
                return Err(MemoryError::bad_request("phonetic codes must not be empty"));
            }
        }
        if let Some(ppr) = &self.ppr {
            if ppr.seeds.is_empty() {
                return Err(MemoryError::bad_request("ppr requires seeds"));
            }
        }
        if let Some(time) = self.temporal {
            caps::check_as_of(Some(time.start))?;
            caps::check_as_of(Some(time.end))?;
        }
        if let Some(replay) = self.replay {
            caps::check_as_of(Some(replay.now))?;
            replay.blend_weights.normalized().map_err(|error| {
                MemoryError::bad_request(format!("replay.blend_weights: {error}"))
            })?;
        }
        if self
            .query
            .as_ref()
            .is_none_or(|query| query.trim().is_empty())
            && self.query_vector.is_none()
            && self.phonetic_codes.is_empty()
            && self.ppr.is_none()
            && self.temporal.is_none()
        {
            return Err(MemoryError::bad_request("hybrid search requires a channel"));
        }
        Ok(())
    }
}
